dashboard.definition:
{
	"title": "SAP Services",
	"description": "",
	"inputs": {
		"input_global_trp": {
			"options": {"defaultValue": "-30d@d,now", "token": "global_time"},
			"title": "Global Time Range",
			"type": "input.timerange"
		},
		"input_nav_dropdown": {
			"type": "input.dropdown",
			"title": "Navigate to Dashboard",
			"options": {
				"items": [
					{"label": "Overview", "value": "logserv_overview"},
					{"label": "DNS Analytics", "value": "logserv_dns_analytics"},
					{"label": "HANA Audit", "value": "logserv_hana_audit"},
					{"label": "HANA Trace", "value": "logserv_hana_trace"},
					{"label": "Web Dispatcher", "value": "logserv_web_dispatcher"},
					{"label": "Host Details", "value": "logserv_host_details"},
					{"label": "ABAP Security", "value": "logserv_abap_security"},
					{"label": "ABAP Operations", "value": "logserv_abap_operations"},
					{"label": "Cloud Connector", "value": "logserv_cloud_connector"},
					{"label": "Linux", "value": "logserv_linux"},
					{"label": "Windows", "value": "logserv_windows"},
					{"label": "Proxy", "value": "logserv_proxy"},
					{"label": "Environment Health", "value": "logserv_environment_health"}
				],
				"token": "nav_target"
			}
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "$global_time.earliest$",
						"latest": "$global_time.latest$"
					}
				}
			}
		}
	},
	"visualizations": {
		"viz_kpi_total": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_total"},
			"title": "Total Events",
			"options": {
				"majorValue": "> primary | seriesByName('total') | lastPoint()",
				"backgroundColor": "transparent",
				"sparklineDisplay": "off",
				"trendDisplay": "off"
			}
		},
		"viz_kpi_auth_fail": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_auth_fail"},
			"title": "Auth Failures",
			"options": {
				"majorValue": "> primary | seriesByName('failures') | lastPoint()",
				"majorColor": "#dc4e41",
				"backgroundColor": "transparent",
				"sparklineDisplay": "off",
				"trendDisplay": "off"
			}
		},
		"viz_kpi_router_errors": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_router_errors"},
			"title": "Router Errors",
			"options": {
				"majorValue": "> primary | seriesByName('errors') | lastPoint()",
				"majorColor": "#f1813f",
				"backgroundColor": "transparent",
				"sparklineDisplay": "off",
				"trendDisplay": "off"
			}
		},
		"viz_volume_by_type": {
			"type": "splunk.line",
			"dataSources": {"primary": "ds_volume_by_type"},
			"title": "Event Volume by Service",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {"backgroundColor": "transparent", "xAxisTitleVisibility": "hide", "yAxisTitleVisibility": "hide"}
		},
		"viz_router_connections": {
			"type": "splunk.table",
			"dataSources": {"primary": "ds_router_connections"},
			"title": "SAP Router Connections",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)"
				}
			}
		},
		"viz_router_actions": {
			"type": "splunk.column",
			"dataSources": {"primary": "ds_router_actions"},
			"title": "Router Actions Over Time",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"stackMode": "stacked",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			}
		},
		"viz_router_errors": {
			"type": "splunk.table",
			"dataSources": {"primary": "ds_router_errors"},
			"title": "Router Error Details",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)"
				}
			}
		},
		"viz_auth_events": {
			"type": "splunk.table",
			"dataSources": {"primary": "ds_auth_events"},
			"title": "Sapstartsrv Authentication Events",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)"
				}
			}
		},
		"viz_ssl_events": {
			"type": "splunk.table",
			"dataSources": {"primary": "ds_ssl_events"},
			"title": "Sapstartsrv SSL/TLS Events",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)"
				}
			}
		},
		"viz_hostexec_severity": {
			"type": "splunk.pie",
			"dataSources": {"primary": "ds_hostexec_severity"},
			"title": "Host Agent Severity",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {"showDonutHole": true, "backgroundColor": "transparent"}
		},
		"viz_rect_r1l": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r1r": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r2l": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r2r": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r3l": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r3m": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r3r": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_nav_go": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_nav_go"},
			"options": {
				"majorValue": "> primary | seriesByName('label') | lastPoint()",
				"backgroundColor": "#0877a6", "majorColor": "#ffffff",
				"sparklineDisplay": "off", "trendDisplay": "off", "majorFontSize": 14
			},
			"eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "/app/splunk_app_sap_logserv/$nav_target$?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$", "newTab": false}}]
		}
	},
	"dataSources": {
		"ds_kpi_total": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype IN (\"sap:sapstartsrv\", \"sap:saphostexec\", \"sap:saprouter\") | stats count as total"}
		},
		"ds_kpi_auth_fail": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"sap:sapstartsrv\" is_auth_event=\"true\" auth_result=\"failure\" | stats count as failures"}
		},
		"ds_kpi_router_errors": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"sap:saprouter\" is_error=\"true\" | stats count as errors"}
		},
		"ds_volume_by_type": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype IN (\"sap:sapstartsrv\", \"sap:saphostexec\", \"sap:saprouter\") | timechart span=1d count by sourcetype"}
		},
		"ds_router_connections": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"sap:saprouter\" | where isnotnull(action) OR isnotnull(src_ip) OR isnotnull(peer_ip) | table _time action connection_id src_ip src_port peer_ip peer_port | sort -_time | head 30 | rename action as Action connection_id as \"Conn ID\" src_ip as \"Source IP\" src_port as \"Src Port\" peer_ip as \"Peer IP\" peer_port as \"Peer Port\""}
		},
		"ds_router_actions": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"sap:saprouter\" action=* | timechart span=1d count by action"}
		},
		"ds_router_errors": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"sap:saprouter\" is_error=\"true\" | table _time error_function return_code peer_ip source_file error_detail | sort -_time | head 20 | rename error_function as \"Error Function\" return_code as \"Return Code\" peer_ip as \"Peer IP\" source_file as \"Source File\" error_detail as \"Error Detail\""}
		},
		"ds_auth_events": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"sap:sapstartsrv\" is_auth_event=\"true\" | table _time auth_user remote_ip webmethod auth_result | sort -_time | head 30 | rename auth_user as User remote_ip as \"Remote IP\" webmethod as Method auth_result as Result"}
		},
		"ds_ssl_events": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"sap:sapstartsrv\" is_ssl_event=\"true\" | table _time ssl_peer_ip tls_client_version ssl_error_code ssl_state | sort -_time | head 30 | rename ssl_peer_ip as \"Peer IP\" tls_client_version as \"TLS Version\" ssl_error_code as \"Error Code\" ssl_state as State"}
		},
		"ds_hostexec_severity": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"sap:saphostexec\" severity=* | stats count by severity | sort -count"}
		},
		"ds_nav_go": {
			"type": "ds.search",
			"options": {"query": "| makeresults | eval label=\"Go >\"", "queryParameters": {"earliest": "-1m", "latest": "now"}}
		}
	},
	"layout": {
		"globalInputs": ["input_global_trp", "input_nav_dropdown"],
		"layoutDefinitions": {
			"layout_1": {
				"options": {"height": 1200, "width": 1920},
				"structure": [
					{"item": "viz_nav_go", "type": "block", "position": {"x": 1790, "y": 0, "w": 120, "h": 35}},
					{"item": "viz_kpi_total", "type": "block", "position": {"x": 10, "y": 45, "w": 300, "h": 90}},
					{"item": "viz_kpi_auth_fail", "type": "block", "position": {"x": 320, "y": 45, "w": 300, "h": 90}},
					{"item": "viz_kpi_router_errors", "type": "block", "position": {"x": 630, "y": 45, "w": 300, "h": 90}},
					{"item": "viz_rect_r1l", "type": "block", "position": {"x": 10, "y": 150, "w": 940, "h": 340}},
					{"item": "viz_volume_by_type", "type": "block", "position": {"x": 20, "y": 155, "w": 920, "h": 330}},
					{"item": "viz_rect_r1r", "type": "block", "position": {"x": 960, "y": 150, "w": 950, "h": 340}},
					{"item": "viz_router_actions", "type": "block", "position": {"x": 970, "y": 155, "w": 930, "h": 330}},
					{"item": "viz_rect_r2l", "type": "block", "position": {"x": 10, "y": 505, "w": 950, "h": 340}},
					{"item": "viz_router_connections", "type": "block", "position": {"x": 20, "y": 510, "w": 930, "h": 330}},
					{"item": "viz_rect_r2r", "type": "block", "position": {"x": 970, "y": 505, "w": 940, "h": 340}},
					{"item": "viz_router_errors", "type": "block", "position": {"x": 980, "y": 510, "w": 920, "h": 330}},
					{"item": "viz_rect_r3l", "type": "block", "position": {"x": 10, "y": 860, "w": 620, "h": 330}},
					{"item": "viz_auth_events", "type": "block", "position": {"x": 20, "y": 865, "w": 600, "h": 320}},
					{"item": "viz_rect_r3m", "type": "block", "position": {"x": 640, "y": 860, "w": 640, "h": 330}},
					{"item": "viz_ssl_events", "type": "block", "position": {"x": 650, "y": 865, "w": 620, "h": 320}},
					{"item": "viz_rect_r3r", "type": "block", "position": {"x": 1290, "y": 860, "w": 620, "h": 330}},
					{"item": "viz_hostexec_severity", "type": "block", "position": {"x": 1300, "y": 865, "w": 600, "h": 320}}
				],
				"type": "absolute"
			}
		},
		"options": {},
		"tabs": {"items": [{"label": "New tab", "layoutId": "layout_1"}]}
	}
}
